{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Procainamide, which shares the 4-substituted benzamide and ethylenediamine amide scaffold with the query, has absolute oral bioavailability of 75% after oral vs IV dosing in normal volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "N-acetylprocainamide, a close benzamide analogue, has absolute bioavailability of 87% measured by stable-isotope IV comparison in normal subjects, supporting high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Haloperidol, a 4-chlorophenyl drug with a basic amine, has absolute oral bioavailability of 60–70% in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Sematilide, a basic benzamide antiarrhythmic, has absolute bioavailability of about 58–59%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Molsidomine, a morpholine-containing drug, has absolute bioavailability of 44 ± 15%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Indoramin, a basic benzamide, can have low median oral bioavailability (7.7%) in tablet form, but this is variable and reflects extensive first-pass metabolism; its lower similarity limits transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small 4-chlorobenzamide with a morpholinoethyl side chain. Close analogues—procainamide, N-acetylprocainamide, sematilide, haloperidol, and molsidomine—consistently show absolute oral bioavailability above 20%, mostly 44–90%. The low-F analogues are less similar and have specific first-pass or efflux liabilities. Thus high F is the better-supported prediction, and the fed state is not expected to lower F below the 20% threshold.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is included.",
    "The supplied records do not specify fed-state conditions; the prediction assumes the fed state does not reduce the extent of absorption below threshold.",
    "Some analogues, especially haloperidol and indoramin, show wide interindividual variability, so the exact quantitative F for the query remains uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

